class Solution {
  public String minCostGoodCaption(String caption) {
    int n = caption.length();
    if (n < 3) return "";
    int INF = Integer.MAX_VALUE / 2;
    int[][] f = new int[n][26 * 3];
    int[] min1 = new int[n], arg1 = new int[n], min2 = new int[n];
    for (int i = n - 1; i >= 0; i--) {
      int ch = caption.charAt(i) - 'a';
      for (int c = 0; c < 26; c++) {
        int cost = Math.abs(ch - c);
        for (int l = 1; l <= 3; l++) {
          int best = INF;
          if (i == n - 1) {
            if (l == 3) best = 0;
          } else {
            best = f[i + 1][c * 3 + Math.min(l + 1, 3) - 1];
            if (l == 3) {
              int other = arg1[i + 1] == c ? min2[i + 1] : min1[i + 1];
              best = Math.min(best, other);
            }
          }
          f[i][c * 3 + l - 1] = best >= INF ? INF : best + cost;
        }
      }
      min1[i] = min2[i] = INF;
      arg1[i] = -1;
      for (int c = 0; c < 26; c++) {
        int v = f[i][c * 3];
        if (v < min1[i]) {
          min2[i] = min1[i];
          min1[i] = v;
          arg1[i] = c;
        } else if (v < min2[i]) min2[i] = v;
      }
    }
    if (min1[0] >= INF) return "";
    char[] out = new char[n];
    int cur = arg1[0], run = 1;
    for (int c = 0; c < 26; c++) {
      if (f[0][c * 3] == min1[0]) {
        cur = c;
        break;
      }
    }
    out[0] = (char) ('a' + cur);
    for (int i = 1; i < n; i++) {
      int rem = f[i - 1][cur * 3 + run - 1] - Math.abs(caption.charAt(i - 1) - 'a' - cur);
      int next = -1, nrun = 0;
      for (int c = 0; c < 26 && next < 0; c++) {
        if (c == cur) {
          int r2 = Math.min(run + 1, 3);
          if (f[i][c * 3 + r2 - 1] == rem) {
            next = c;
            nrun = r2;
          }
        } else if (run == 3 && f[i][c * 3] == rem) {
          next = c;
          nrun = 1;
        }
      }
      cur = next;
      run = nrun;
      out[i] = (char) ('a' + cur);
    }
    return new String(out);
  }
}
